import { promises as fs } from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

let writeQueue = Promise.resolve();

async function ensureFile() {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, '[]', 'utf8');
  }
}

export async function getAllBooks() {
  await ensureFile();
  let raw;
  try {
    raw = await fs.readFile(DATA_FILE, 'utf8');
  } catch {
    return [];
  }
  try {
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

export async function saveBooks(books) {
  const run = writeQueue.then(() =>
    fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8')
  );
  writeQueue = run.catch(() => {});
  await run;
}

export async function getBookById(id) {
  const books = await getAllBooks();
  return books.find((b) => b.id === id) ?? null;
}

export function normalizeStatus(value) {
  return value === 'finished' ? 'finished' : 'reading';
}

export async function createBook(input) {
  const books = await getAllBooks();
  const now = Date.now();
  const status = normalizeStatus(input.status);
  const book = {
    id: crypto.randomUUID(),
    title: (input.title ?? '').trim(),
    author: (input.author ?? '').trim(),
    notes: (input.notes ?? '').trim(),
    status,
    createdAt: now,
    updatedAt: now,
    finishedAt: status === 'finished' ? now : null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function updateBook(id, patch) {
  const books = await getAllBooks();
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return null;

  const current = books[index];
  const now = Date.now();
  const next = { ...current };

  if (typeof patch.title === 'string') next.title = patch.title.trim();
  if (typeof patch.author === 'string') next.author = patch.author.trim();
  if (typeof patch.notes === 'string') next.notes = patch.notes.trim();

  if (patch.status === 'reading' || patch.status === 'finished') {
    next.status = patch.status;
    next.finishedAt =
      patch.status === 'finished' ? current.finishedAt ?? now : null;
  }

  next.updatedAt = now;
  books[index] = next;
  await saveBooks(books);
  return next;
}

export async function deleteBook(id) {
  const books = await getAllBooks();
  const filtered = books.filter((b) => b.id !== id);
  if (filtered.length === books.length) return false;
  await saveBooks(filtered);
  return true;
}

