import { NextResponse } from 'next/server';
import {
  getBookById,
  updateBook,
  deleteBook,
} from '../../../../lib/books.js';

export const dynamic = 'force-dynamic';

export async function GET(request, { params }) {
  const { id } = await params;
  const book = await getBookById(id);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json({ book });
}

export async function PATCH(request, { params }) {
  const { id } = await params;
  const body = await request.json().catch(() => ({}));
  const book = await updateBook(id, body);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json({ book });
}

export async function DELETE(request, { params }) {
  const { id } = await params;
  const removed = await deleteBook(id);
  if (!removed) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }
  return NextResponse.json({ ok: true });
}

export async function POST(request, { params }) {
  const { id } = await params;
  const form = await request.formData();
  const action = String(form.get('action') ?? 'update');

  if (action === 'delete') {
    await deleteBook(id);
    return NextResponse.redirect(new URL('/', request.url), {
      status: 303,
    });
  }

  const patch = {};
  const title = form.get('title');
  if (title != null) patch.title = String(title);
  const author = form.get('author');
  if (author != null) patch.author = String(author);
  const notes = form.get('notes');
  if (notes != null) patch.notes = String(notes);
  const status = form.get('status');
  if (status != null) patch.status = String(status);

  const book = await updateBook(id, patch);
  if (!book) {
    return NextResponse.json({ error: 'Book not found' }, { status: 404 });
  }

  return NextResponse.redirect(
    new URL(`/books/${book.id}`, request.url),
    { status: 303 }
  );
}

