args.content:
:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --ink: #1f2430;
  --muted: #6b7280;
  --line: #e6e3db;
  --accent: #3b5a4a;
  --accent-ink: #ffffff;
  --reading: #4f6d8c;
  --finished: #6b7a4f;
  --danger: #9b3b3b;
  --radius: 10px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,
    Helvetica, Arial, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

.shell {
  max-width: 760px;
  margin: 0 auto;
  padding: 0 20px 60px;
}

.topbar {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 28px 0 18px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 28px;
}

.brand {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--ink);
  text-decoration: none;
  letter-spacing: -0.01em;
}

.topbar nav a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}

.topbar nav a:hover {
  text-decoration: underline;
}

.footer {
  margin-top: 48px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.85rem;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 6px;
  letter-spacing: -0.02em;
}

h2 {
  font-size: 1.05rem;
  margin: 0 0 14px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}

a {
  color: var(--accent);
}

.section {
  margin-bottom: 36px;
}

.empty {
  color: var(--muted);
  font-style: italic;
  padding: 8px 0;
}

.grid {
  display: grid;
  gap: 14px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.card-main {
  min-width: 0;
}

.card-title {
  font-size: 1.08rem;
  font-weight: 600;
  margin: 0;
}

.card-title a {
  color: var(--ink);
  text-decoration: none;
}

.card-title a:hover {
  color: var(--accent);
  text-decoration: underline;
}

.card-author {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 0.92rem;
}

.card-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  flex-shrink: 0;
}

.badge {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 999px;
  color: #fff;
  background: var(--reading);
}

.badge.finished {
  background: var(--finished);
}

.meta {
  color: var(--muted);
  font-size: 0.85rem;
  margin-top: 6px;
}

button,
.btn {
  font: inherit;
  cursor: pointer;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  padding: 7px 12px;
  font-size: 0.88rem;
  font-weight: 600;
  white-space: nowrap;
}

button:hover,
.btn:hover {
  border-color: var(--accent);
}

button.primary,
.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

button.danger,
.btn.danger {
  color: var(--danger);
  border-color: var(--line);
  background: var(--surface);
}

button.danger:hover,
.btn.danger:hover {
  border-color: var(--danger);
}

form {
  margin: 0;
}

.form {
  max-width: 520px;
}

.field {
  margin-bottom: 18px;
}

.field label {
  display: block;
  font-weight: 600;
  font-size: 0.9rem;
  margin-bottom: 6px;
}

.field input,
.field textarea,
.field select {
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font: inherit;
  background: var(--surface);
  color: var(--ink);
}

.field input:focus,
.field textarea:focus,
.field select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(59, 90, 74, 0.12);
}

.field textarea {
  min-height: 130px;
  resize: vertical;
}

.form-actions {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-top: 24px;
}

.detail-head {
  margin-bottom: 24px;
}

.detail-head h1 {
  margin-bottom: 4px;
}

.detail-author {
  color: var(--muted);
  font-size: 1rem;
  margin: 0;
}

.detail-note {
  white-space: pre-wrap;
  margin: 0;
}

.note-empty {
  color: var(--muted);
  font-style: italic;
}

.row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

.back-link {
  display: inline-block;
  margin-bottom: 18px;
  font-size: 0.9rem;
  text-decoration: none;
  color: var(--muted);
}

.back-link:hover {
  color: var(--accent);
}

.share-box {
  margin: 24px 0;
  padding: 12px 14px;
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: 8px;
  font-size: 0.85rem;
  color: var(--muted);
  word-break: break-all;
}

.share-box code {
  color: var(--ink);
}

.error-page {
  text-align: center;
  padding: 40px 0;
}

