import Link from 'next/link';
import { getAllBooks } from '../lib/books.js';

export const dynamic = 'force-dynamic';

function formatDate(ts) {
  if (!ts) return null;
  return new Date(ts).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

function BookCard({ book }) {
  const isFinished = book.status === 'finished';
  const toggleStatus = isFinished ? 'reading' : 'finished';
  const toggleLabel = isFinished ? 'Mark as reading' : 'Mark as finished';

  return (
    <article className="card">
      <div className="card-main">
        <p className="card-title">
          <Link href={`/books/${book.id}`}>{book.title}</Link>
        </p>
        {book.author ? (
          <p className="card-author">by {book.author}</p>
        ) : null}
        {isFinished && book.finishedAt ? (
          <p className="meta">Finished {formatDate(book.finishedAt)}</p>
        ) : null}
      </div>
      <div className="card-actions">
        <form action={`/api/books/${book.id}`} method="post">
          <input type="hidden" name="action" value="update" />
          <input type="hidden" name="status" value={toggleStatus} />
          <button type="submit">{toggleLabel}</button>
        </form>
      </div>
    </article>
  );
}

export default async function HomePage() {
  const books = await getAllBooks();
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.updatedAt - a.updatedAt);
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt - a.finishedAt);

  return (
    <div>
      <h1>Your books</h1>

      <section className="section">
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">
            Nothing in progress. <Link href="/new">Add a book</Link> to get
            started.
          </p>
        ) : (
          <div className="grid">
            {reading.map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        )}
      </section>

      <section className="section">
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <div className="grid">
            {finished.map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

