import Link from 'next/link';
import { headers } from 'next/headers';
import { getBookById } from '../../../lib/books.js';

export const dynamic = 'force-dynamic';

function formatDate(ts) {
  if (!ts) return null;
  return new Date(ts).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBookById(id);
  return { title: book ? `${book.title} — Reading List` : 'Book not found' };
}

export default async function BookDetailPage({ params }) {
  const { id } = await params;
  const book = await getBookById(id);

  if (!book) {
    return (
      <div className="error-page">
        <h1>Book not found</h1>
        <p className="empty">
          This book may have been deleted, or the link is wrong.
        </p>
        <p>
          <Link href="/" className="btn">
            Back to books
          </Link>
        </p>
      </div>
    );
  }

  const h = await headers();
  const proto = h.get('x-forwarded-proto') || 'http';
  const host = h.get('host') || 'localhost:3000';
  const shareUrl = `${proto}://${host}/books/${book.id}`;
  const isFinished = book.status === 'finished';

  return (
    <div>
      <Link href="/" className="back-link">
        &larr; Back to books
      </Link>

      <div className="detail-head">
        <div className="row" style={{ marginBottom: 8 }}>
          <span className={`badge${isFinished ? ' finished' : ''}`}>
            {isFinished ? 'Finished' : 'Reading'}
          </span>
          {isFinished && book.finishedAt ? (
            <span className="meta" style={{ margin: 0 }}>
              Finished {formatDate(book.finishedAt)}
            </span>
          ) : null}
        </div>
        <h1>{book.title}</h1>
        {book.author ? (
          <p className="detail-author">by {book.author}</p>
        ) : null}
      </div>

      <div className="share-box">
        Share this book:{' '}
        <code>{shareUrl}</code>
      </div>

      <form
        className="form"
        action={`/api/books/${book.id}`}
        method="post"
        style={{ marginTop: 28 }}
      >
        <input type="hidden" name="action" value="update" />

        <div className="field">
          <label htmlFor="status">Status</label>
          <select
            id="status"
            name="status"
            defaultValue={book.status}
          >
            <option value="reading">Currently reading</option>
            <option value="finished">Finished</option>
          </select>
        </div>

        <div className="field">
          <label htmlFor="notes">Notes</label>
          <textarea id="notes" name="notes" defaultValue={book.notes} />
        </div>

        <div className="form-actions">
          <button type="submit" className="primary">
            Save changes
          </button>
        </div>
      </form>

      <form
        action={`/api/books/${book.id}`}
        method="post"
        style={{ marginTop: 28 }}
        onSubmit="return confirm('Delete this book permanently?')"
      >
        <input type="hidden" name="action" value="delete" />
        <button type="submit" className="danger">
          Delete book
        </button>
      </form>
    </div>
  );
}

